"""Synthetic firmware images for tests, samples and the demo project - original bytes generated by RAD IDE, never
a manufacturer's software.

``make_image(arch)`` builds a small flash image for one CPU family with what real ECU / embedded images have:
a vector table or boot header, functions (prologue, body, calls, epilogue, literal pools) encoded with the real
instruction set, a pointer table, identification strings, calibration tables (axes, curves and 2-D maps whose
addresses the code references) and erased-flash fill. The result records every address it placed, so tests can
check detection, base address, disassembly and cross references against known answers.
"""
from __future__ import annotations

import random
import struct
from dataclasses import dataclass, field

ARCHES = ["arm-thumb", "ppc", "ppc-vle", "tricore", "c166", "hc12", "sh2", "v850", "m68k", "8051"]

# arch -> (default base, image size, endianness, pointer size)
LAYOUT = {
    "arm-thumb": (0x08000000, 0x10000, "little", 4),
    "ppc": (0x00000000, 0x10000, "big", 4),
    "ppc-vle": (0x00000000, 0x10000, "big", 4),
    "tricore": (0x80000000, 0x10000, "little", 4),
    "c166": (0x00000000, 0x10000, "little", 2),
    "hc12": (0x00008000, 0x8000, "big", 2),
    "sh2": (0x00000000, 0x10000, "big", 4),
    "v850": (0x00000000, 0x10000, "little", 4),
    "m68k": (0x00000000, 0x10000, "big", 4),
    "8051": (0x00000000, 0x8000, "big", 2),
}


@dataclass
class Table:
    name: str
    address: int
    rows: int
    cols: int
    width: int              # bytes per value
    kind: str               # "axis" | "curve" | "map"


@dataclass
class SynthImage:
    arch: str
    base: int
    data: bytearray
    endian: str
    functions: list[int] = field(default_factory=list)       # entry addresses
    entry: int = 0
    tables: list[Table] = field(default_factory=list)
    strings: dict[str, int] = field(default_factory=dict)    # text -> address
    xrefs: dict[int, list[int]] = field(default_factory=dict)  # table address -> instruction addresses
    code_end: int = 0                                        # offset where code stops
    calib_start: int = 0                                     # offset of the calibration area

    @property
    def size(self) -> int:
        return len(self.data)

    def bytes(self) -> bytes:
        return bytes(self.data)


class _Asm:
    """Little helper collecting bytes at an address."""
    def __init__(self, endian: str, addr: int):
        self.e = endian
        self.addr0 = addr
        self.buf = bytearray()

    @property
    def pc(self) -> int:
        return self.addr0 + len(self.buf)

    def b(self, *vals: int):
        self.buf += bytes(v & 0xFF for v in vals)

    def h(self, v: int, endian: str | None = None):
        self.buf += (v & 0xFFFF).to_bytes(2, endian or self.e)

    def w(self, v: int, endian: str | None = None):
        self.buf += (v & 0xFFFFFFFF).to_bytes(4, endian or self.e)

    def align(self, n: int, fill: int = 0):
        while len(self.buf) % n:
            self.buf.append(fill)


# ============================================================================ per-arch function encoders
def _pick(rnd, seq):
    """One element; always consumes exactly one random number (both code passes stay in step)."""
    return seq[int(rnd.random() * len(seq))]


def _thumb_bl(pc: int, target: int) -> tuple[int, int]:
    off = target - (pc + 4)
    s = (off >> 24) & 1
    i1 = (off >> 23) & 1
    i2 = (off >> 22) & 1
    imm10 = (off >> 12) & 0x3FF
    imm11 = (off >> 1) & 0x7FF
    j1 = ((~i1) & 1) ^ s
    j2 = ((~i2) & 1) ^ s
    return 0xF000 | (s << 10) | imm10, 0xD000 | (j1 << 13) | (j2 << 11) | imm11


def _fn_thumb(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    a.h(0xB5F0 if rnd.random() < 0.6 else 0xB510)           # push {r4-r7,lr} / {r4,lr}
    lits = []
    for _ in range(rnd.randint(6, 18)):
        r = rnd.random()
        rd, rn, rm = rnd.randrange(8), rnd.randrange(8), rnd.randrange(8)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            lits.append((len(a.buf), rd, ref))
            xrefs.setdefault(ref, []).append(a.pc)
            a.h(0x4800 | (rd << 8))                           # ldr rd,[pc,#imm] (fixed below)
            a.h(0x8800 | (rd << 3) | rd)                       # ldrh rd,[rd]
        elif r < 0.30:
            a.h(0x2000 | (rd << 8) | rnd.randrange(256))       # movs
        elif r < 0.42:
            a.h(0x3000 | (rd << 8) | rnd.randrange(1, 64))     # adds
        elif r < 0.55:
            a.h(0x6800 | (rnd.randrange(8) << 6) | (rn << 3) | rd)   # ldr rd,[rn,#]
        elif r < 0.65:
            a.h(0x6000 | (rnd.randrange(8) << 6) | (rn << 3) | rd)   # str
        elif r < 0.73:
            a.h(0x1800 | (rm << 6) | (rn << 3) | rd)           # adds rd,rn,rm
        elif r < 0.80:
            a.h(0x2800 | (rn << 8) | rnd.randrange(256))       # cmp
            a.h(0xD100)                                         # bne (skips the next halfword)
            a.h(0x3001)                                         # adds r0,#1
        elif r < 0.92 and callees:
            hi, lo = _thumb_bl(a.pc, _pick(rnd, callees))
            a.h(hi)
            a.h(lo)
        else:
            a.h(0x0000 | (rnd.randrange(1, 31) << 6) | (rm << 3) | rd)   # lsls
    a.h(0xBDF0 if rnd.random() < 0.7 else 0xBD10)           # pop {..,pc}
    if lits:
        a.align(4, 0)
        for pos, rd, ref in lits:
            lit = a.pc
            a.w(ref)
            pc = a.addr0 + pos
            imm = (lit - ((pc + 4) & ~3)) // 4
            a.buf[pos:pos + 2] = (0x4800 | (rd << 8) | imm).to_bytes(2, "little")


def _ppc_hi_lo(v: int) -> tuple[int, int]:
    lo = v & 0xFFFF
    hi = ((v >> 16) + (1 if lo & 0x8000 else 0)) & 0xFFFF
    return hi, lo


def _fn_ppc(a: _Asm, rnd, callees, refs, xrefs):
    a.align(4)
    a.w(0x9421FFF0)                  # stwu r1,-16(r1)
    a.w(0x7C0802A6)                  # mflr r0
    a.w(0x90010014)                  # stw r0,20(r1)
    for _ in range(rnd.randint(5, 16)):
        r = rnd.random()
        rd, ra, rb = rnd.randrange(3, 12), rnd.randrange(3, 12), rnd.randrange(3, 12)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            hi, lo = _ppc_hi_lo(ref)
            xrefs.setdefault(ref, []).append(a.pc + 4)       # the load completes the address
            a.w(0x3C000000 | (rd << 21) | hi)                    # lis rd,hi
            a.w(0xA0000000 | (rd << 21) | (rd << 16) | lo)       # lhz rd,lo(rd)
        elif r < 0.3:
            a.w(0x38000000 | (rd << 21) | rnd.randrange(0x100))  # li
        elif r < 0.45:
            a.w(0x7C000214 | (rd << 21) | (ra << 16) | (rb << 11))   # add
        elif r < 0.55:
            a.w(0x80000000 | (rd << 21) | (ra << 16) | (rnd.randrange(16) * 4))   # lwz
        elif r < 0.65:
            a.w(0x90000000 | (rd << 21) | (ra << 16) | (rnd.randrange(16) * 4))   # stw
        elif r < 0.75:
            a.w(0x2C000000 | (ra << 16) | rnd.randrange(100))    # cmpwi
            a.w(0x40820008)                                      # bne +8
            a.w(0x38630001)                                      # addi r3,r3,1
        elif r < 0.9 and callees:
            off = _pick(rnd, callees) - a.pc
            a.w(0x48000001 | (off & 0x03FFFFFC))                 # bl
        else:
            a.w(0x5400103A | (rd << 16) | (ra << 21))            # rlwinm (slwi 2)
    a.w(0x80010014)                  # lwz r0,20(r1)
    a.w(0x7C0803A6)                  # mtlr r0
    a.w(0x38210010)                  # addi r1,r1,16
    a.w(0x4E800020)                  # blr


def _vle_r(r: int) -> int:
    """VLE 4-bit register field (r0-r7, r24-r31)."""
    return r if r < 8 else r - 16


def _fn_vle(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    a.w(0x182106F0)                  # e_stwu r1,-16(r1)
    a.h(0x0080)                      # se_mflr r0
    a.w(0x54010014)                  # e_stw r0,20(r1)
    for _ in range(rnd.randint(6, 18)):
        r = rnd.random()
        rx, ry = rnd.randrange(3, 8), rnd.randrange(3, 8)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            hi, lo = _ppc_hi_lo(ref)
            xrefs.setdefault(ref, []).append(a.pc + 4)
            # e_lis rD,hi  (0111 00dd ddd0 uuuu u111 00uu uuuu uuuu)
            ui = hi
            a.w(0x7000E000 | (rx << 21) | ((ui >> 11) << 16) | (ui & 0x7FF))
            a.w(0x58000000 | (rx << 21) | (rx << 16) | lo)       # e_lhz rx,lo(rx)
        elif r < 0.35:
            a.h(0x4800 | (rnd.randrange(128) << 4) | _vle_r(rx))   # se_li
        elif r < 0.5:
            a.h(0x0400 | (_vle_r(ry) << 4) | _vle_r(rx))         # se_add
        elif r < 0.62:
            a.h(0xC000 | (rnd.randrange(16) << 8) | (_vle_r(ry) << 4) | _vle_r(rx))   # se_lwz
        elif r < 0.72:
            a.h(0xD000 | (rnd.randrange(16) << 8) | (_vle_r(ry) << 4) | _vle_r(rx))   # se_stw
        elif r < 0.85 and callees:
            off = _pick(rnd, callees) - a.pc
            a.w(0x78000001 | (off & 0x01FFFFFE))                 # e_bl
        else:
            a.h(0x2A00 | (rnd.randrange(32) << 4) | _vle_r(rx))  # se_cmpi
            a.h(0xE200 | 2)                                      # se_bne +4
            a.h(0x2000 | _vle_r(rx))                             # se_addi rx,1
    a.w(0x50010014)                  # e_lwz r0,20(r1)
    a.h(0x0090)                      # se_mtlr r0
    a.w(0x1C210010)                  # e_add16i r1,r1,16
    a.h(0x0004)                      # se_blr


def _tc_bol(op: int, a_reg: int, b_reg: int, off: int) -> int:
    off &= 0xFFFF
    return (op | (a_reg << 8) | (b_reg << 12) | ((off & 0x3F) << 16) | (((off >> 6) & 0xF) << 28)
            | (((off >> 10) & 0x3F) << 22))


def _fn_tricore(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    for _ in range(rnd.randint(6, 18)):
        r = rnd.random()
        d = rnd.randrange(2, 8)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            hi, lo = _ppc_hi_lo(ref)
            xrefs.setdefault(ref, []).append(a.pc + 4)       # LEA completes the address
            a.w(0x91 | (hi << 12) | (2 << 28))                   # movh.a a2,#hi
            a.w(_tc_bol(0xD9, 2, 2, lo))                         # lea a2,[a2]lo
            a.w(_tc_bol(0x19, d, 2, 0))                          # ld.w dX,[a2]0
        elif r < 0.3:
            a.h(0xDA | (rnd.randrange(256) << 8))                # mov d15,#c
        elif r < 0.42:
            a.h(0x1F92)                                          # add d15,d15,#1
        elif r < 0.55:
            a.h(0x4C | (0xF << 8) | (rnd.randrange(16) << 12))   # ld.w d15,[a15]#
        elif r < 0.65:
            a.h(0x6C | (0xF << 8) | (rnd.randrange(16) << 12))   # st.w [a15]#,d15
        elif r < 0.75:
            a.h(0x045E)                                          # jne d15,#0,+8
            a.h(0x0002 | (d << 8))                               # mov dX,d0
        elif r < 0.9 and callees:
            disp = ((_pick(rnd, callees) - a.pc) >> 1) & 0xFFFFFF
            a.w(0x6D | (((disp >> 16) & 0xFF) << 8) | ((disp & 0xFFFF) << 16))   # call
        else:
            a.h(0xF0A2 | (d << 8))                               # sub dX,d15
    a.h(0x9000)                                                  # ret


def _fn_c166(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    a.b(0xEC, 0xFD)                  # push R13
    for _ in range(rnd.randint(6, 16)):
        r = rnd.random()
        rw = rnd.randrange(1, 12)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            xrefs.setdefault(ref, []).append(a.pc)
            a.b(0xF2, 0xF0 | rw, ref & 0xFF, (ref >> 8) & 0xFF)   # mov Rw,mem
        elif r < 0.3:
            a.b(0xE6, 0xF0 | rw, rnd.randrange(256), rnd.randrange(256))   # mov Rw,#data16
        elif r < 0.45:
            a.b(0x00, (rw << 4) | rnd.randrange(16))             # add Rw,Rw
        elif r < 0.58:
            a.b(0xA8, (rw << 4) | rnd.randrange(16))             # mov Rw,[Rw]
        elif r < 0.68:
            a.b(0xB8, (rw << 4) | rnd.randrange(16))             # mov [Rw],Rw
        elif r < 0.76:
            a.b(0x48, (rw << 4) | rnd.randrange(8))              # cmp Rw,#data3
            a.b(0x3D, 0x01)                                      # jmpr cc_NZ,+2
            a.b(0x08, (rw << 4) | 1)                             # add Rw,#1
        elif r < 0.9 and callees:
            t = _pick(rnd, callees)
            a.b(0xCA, 0x00, t & 0xFF, (t >> 8) & 0xFF)           # calla cc_UC,addr
        else:
            a.b(0xF0, (rw << 4) | rnd.randrange(16))             # mov Rw,Rw
    a.b(0xFC, 0xFD)                  # pop R13
    a.b(0xCB, 0x00)                  # ret


def _fn_hc12(a: _Asm, rnd, callees, refs, xrefs):
    a.b(0x34)                        # pshx
    for _ in range(rnd.randint(5, 14)):
        r = rnd.random()
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            xrefs.setdefault(ref, []).append(a.pc)
            a.b(0xCE, ref >> 8, ref)                             # ldx #table
            a.b(0xEC, 0x00)                                      # ldd 0,x
        elif r < 0.3:
            a.b(0xCC, rnd.randrange(256), rnd.randrange(256))    # ldd #
        elif r < 0.42:
            a.b(0xC3, 0x00, rnd.randrange(1, 64))                # addd #
        elif r < 0.55:
            a.b(0x7C, 0x08, rnd.randrange(0x100))                # std ext
        elif r < 0.65:
            a.b(0xFC, 0x08, rnd.randrange(0x100))                # ldd ext
        elif r < 0.75:
            a.b(0x8C, 0x00, rnd.randrange(100))                  # cpd #
            a.b(0x26, 0x01)                                      # bne +1
            a.b(0x08)                                            # inx
        elif r < 0.9 and callees:
            t = _pick(rnd, callees)
            a.b(0x16, t >> 8, t)                                 # jsr ext
        else:
            a.b(0x86, rnd.randrange(256))                        # ldaa #
    a.b(0x30)                        # pulx
    a.b(0x3D)                        # rts


def _fn_sh2(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    a.h(0x2FE6)                      # mov.l r14,@-r15
    a.h(0x4F22)                      # sts.l pr,@-r15
    a.h(0x6EF3)                      # mov r15,r14
    lits = []
    for _ in range(rnd.randint(5, 14)):
        r = rnd.random()
        n, m = rnd.randrange(1, 8), rnd.randrange(1, 8)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            xrefs.setdefault(ref, []).append(a.pc)
            lits.append((len(a.buf), n, ref))
            a.h(0xD000 | (n << 8))                               # mov.l @(disp,pc),rn
            a.h(0x6001 | (n << 8) | (n << 4))                    # mov.w @rn,rn
        elif r < 0.3:
            a.h(0xE000 | (n << 8) | rnd.randrange(128))          # mov #imm,rn
        elif r < 0.42:
            a.h(0x7000 | (n << 8) | rnd.randrange(1, 64))        # add #imm,rn
        elif r < 0.55:
            a.h(0x6002 | (n << 8) | (m << 4))                    # mov.l @rm,rn
        elif r < 0.65:
            a.h(0x2002 | (n << 8) | (m << 4))                    # mov.l rm,@rn
        elif r < 0.75:
            a.h(0x8800 | rnd.randrange(100))                     # cmp/eq #imm,r0
            a.h(0x8B00)                                          # bf +0 (to next)
        elif r < 0.9 and callees:
            lits.append((len(a.buf), 1, _pick(rnd, callees)))
            a.h(0xD100)                                          # mov.l @(disp,pc),r1
            a.h(0x410B)                                          # jsr @r1
            a.h(0x0009)                                          # nop (delay slot)
        else:
            a.h(0x300C | (n << 8) | (m << 4))                    # add rm,rn
    a.h(0x6FE3)                      # mov r14,r15
    a.h(0x4F26)                      # lds.l @r15+,pr
    a.h(0x000B)                      # rts
    a.h(0x6EF6)                      # mov.l @r15+,r14 (delay slot)
    if lits:
        a.align(4, 0x09)
        if len(a.buf) % 4:
            a.h(0x0009)
        for pos, n, ref in lits:
            lit = a.pc
            a.w(ref)
            pc = a.addr0 + pos
            disp = (lit - ((pc & ~3) + 4)) // 4
            a.buf[pos:pos + 2] = (0xD000 | (n << 8) | disp).to_bytes(2, "big")


def _v850_f1(op6: int, reg1: int, reg2: int) -> int:
    return (reg2 << 11) | (op6 << 5) | reg1


def _fn_v850(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    a.h(_v850_f1(0x12, 0x10, 3))     # add -16,sp
    a.h(_v850_f1(0x3B, 3, 31))       # st.w lp,12[sp]
    a.h(12 | 1)
    for _ in range(rnd.randint(5, 14)):
        r = rnd.random()
        rx, ry = rnd.randrange(6, 20), rnd.randrange(6, 20)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            hi, lo = _ppc_hi_lo(ref)
            xrefs.setdefault(ref, []).append(a.pc + 4)
            a.h(_v850_f1(0x32, 0, rx))                           # movhi hi,r0,rx
            a.h(hi)
            a.h(_v850_f1(0x39, rx, ry))                          # ld.w lo[rx],ry  (lo even -> ld.h)
            a.h(lo & 0xFFFE | 1)
        elif r < 0.3:
            a.h(_v850_f1(0x31, 0, rx))                           # movea imm,r0,rx
            a.h(rnd.randrange(0x1000))
        elif r < 0.45:
            a.h(_v850_f1(0x0E, ry, rx))                          # add ry,rx
        elif r < 0.58:
            a.h(_v850_f1(0x00, ry, rx))                          # mov ry,rx
        elif r < 0.68:
            a.h(_v850_f1(0x13, rnd.randrange(16), rx))           # cmp imm5,rx
        elif r < 0.85 and callees:
            disp = _pick(rnd, callees) - a.pc
            a.h((31 << 11) | (0x1E << 6) | ((disp >> 16) & 0x3F))   # jarl disp22,lp
            a.h(disp & 0xFFFE)
        else:
            a.h(_v850_f1(0x0D, ry, rx))                          # subr ry,rx
    a.h(_v850_f1(0x39, 3, 31))       # ld.w 12[sp],lp
    a.h(12 | 1)
    a.h(_v850_f1(0x30, 3, 3))        # addi 16,sp,sp
    a.h(16)
    a.h(0x007F)                      # jmp [lp]


def _fn_m68k(a: _Asm, rnd, callees, refs, xrefs):
    a.align(2)
    a.h(0x4E56)
    a.h(0xFFF8)                      # link a6,#-8
    a.h(0x48E7)
    a.h(0x3020)                      # movem.l d2-d3/a2,-(sp)
    for _ in range(rnd.randint(5, 14)):
        r = rnd.random()
        d = rnd.randrange(8)
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            xrefs.setdefault(ref, []).append(a.pc)
            a.h(0x41F9 | (2 << 9))                               # lea abs.l,a2
            a.w(ref)
            a.h(0x3012 | (d << 9))                               # move.w (a2),dX
        elif r < 0.3:
            a.h(0x7000 | (d << 9) | rnd.randrange(128))          # moveq
        elif r < 0.42:
            a.h(0xD080 | (d << 9) | rnd.randrange(8))            # add.l dY,dX
        elif r < 0.55:
            a.h(0x2028 | (d << 9))                               # move.l d16(a0),dX
            a.h(rnd.randrange(64) * 2)
        elif r < 0.65:
            a.h(0x4A40 | d)                                      # tst.w dX
            a.h(0x6602)                                          # bne.b +2
            a.h(0x5240 | d)                                      # addq.w #1,dX
        elif r < 0.85 and callees:
            a.h(0x4EB9)                                          # jsr abs.l
            a.w(_pick(rnd, callees))
        else:
            a.h(0xE548 | d)                                      # lsl.w #2,dX
    a.h(0x4CDF)
    a.h(0x040C)                      # movem.l (sp)+,d2-d3/a2
    a.h(0x4E5E)                      # unlk a6
    a.h(0x4E75)                      # rts


def _fn_8051(a: _Asm, rnd, callees, refs, xrefs):
    a.b(0xC0, 0xE0)                  # push acc
    for _ in range(rnd.randint(5, 14)):
        r = rnd.random()
        if r < 0.15 and refs:
            ref = _pick(rnd, refs)
            xrefs.setdefault(ref, []).append(a.pc)
            a.b(0x90, ref >> 8, ref)                             # mov dptr,#table
            a.b(0xE4)                                            # clr a
            a.b(0x93)                                            # movc a,@a+dptr
        elif r < 0.3:
            a.b(0x74, rnd.randrange(256))                        # mov a,#
        elif r < 0.42:
            a.b(0x24, rnd.randrange(256))                        # add a,#
        elif r < 0.52:
            a.b(0xF8 | rnd.randrange(8))                         # mov Rn,a
        elif r < 0.62:
            a.b(0xE5, 0x30 + rnd.randrange(0x40))                # mov a,direct
            a.b(0xF5, 0x30 + rnd.randrange(0x40))                # mov direct,a
        elif r < 0.72:
            a.b(0xB4, rnd.randrange(100), 0x01)                  # cjne a,#,+1
            a.b(0x04)                                            # inc a
        elif r < 0.88 and callees:
            t = _pick(rnd, callees)
            a.b(0x12, t >> 8, t)                                 # lcall
        else:
            a.b(0xE8 | rnd.randrange(8))                         # mov a,Rn
    a.b(0xD0, 0xE0)                  # pop acc
    a.b(0x22)                        # ret


ENCODERS = {"arm-thumb": _fn_thumb, "ppc": _fn_ppc, "ppc-vle": _fn_vle, "tricore": _fn_tricore, "c166": _fn_c166,
            "hc12": _fn_hc12, "sh2": _fn_sh2, "v850": _fn_v850, "m68k": _fn_m68k, "8051": _fn_8051}


# ============================================================================ data
def _axis(n: int, lo: int, hi: int) -> list[int]:
    return [round(lo + (hi - lo) * i / (n - 1)) for i in range(n)]


def _map(rows: int, cols: int, top: int, rnd) -> list[int]:
    out = []
    for r in range(rows):
        for c in range(cols):
            v = top * (0.2 + 0.5 * (r / max(1, rows - 1)) + 0.3 * (c / max(1, cols - 1)) * (r / max(1, rows - 1)))
            out.append(int(v + rnd.uniform(-1, 1)))
    return out


def _pack(vals: list[int], width: int, endian: str) -> bytes:
    return b"".join((v & ((1 << (8 * width)) - 1)).to_bytes(width, endian) for v in vals)


def make_image(arch: str, base: int | None = None, size: int | None = None, seed: int = 1,
               n_funcs: int = 900) -> SynthImage:
    """A synthetic flash image for *arch* (one of :data:`ARCHES`)."""
    if arch not in LAYOUT:
        raise ValueError(f"unknown arch {arch!r}; one of {', '.join(ARCHES)}")
    dbase, dsize, endian, psize = LAYOUT[arch]
    base = dbase if base is None else base
    size = dsize if size is None else size
    rnd = random.Random(seed)
    img = SynthImage(arch, base, bytearray(b"\xFF" * size), endian)
    eight_bit = arch in ("hc12", "8051")
    width = 1 if eight_bit else 2

    # ---- calibration area (upper part of the image): axes, curves and maps
    calib = int(size * 0.62) & ~0xFF
    img.calib_start = calib
    pos = calib
    blob = bytearray()

    def put_table(name, kind, rows, cols, vals, w):
        img.tables.append(Table(name, base + pos + len(blob), rows, cols, w, kind))
        blob.extend(_pack(vals, w, endian))
        while len(blob) % 2:
            blob.append(0)
    n_maps = 4 if eight_bit else 6
    for i in range(n_maps):
        rows, cols = (8, 8) if eight_bit else rnd.choice([(16, 16), (12, 16), (8, 12)])
        top = 200 if eight_bit else rnd.choice([1000, 4000, 30000])
        put_table(f"axis_x{i}", "axis", 1, cols, _axis(cols, 5 if eight_bit else 500, 250 if eight_bit else 7000), width)
        put_table(f"axis_y{i}", "axis", 1, rows, _axis(rows, 10, 100 if eight_bit else 1000), width)
        put_table(f"map{i}", "map", rows, cols, _map(rows, cols, top, rnd), width)
        put_table(f"curve{i}", "curve", 1, 8, _axis(8, 0, 120 if eight_bit else 1200), width)
    img.data[pos:pos + len(blob)] = blob
    pos += len(blob)

    # ---- strings (identification block) + pointer table to the strings and tables
    pos = (pos + 0x40) & ~0xF
    texts = ["RADIDE SYNTHETIC ECU", f"ARCH {arch.upper()}", "SW 1234567890", "X 123 456 78 90",
             "V1.02.003", "BUILD 2026-11-21", "CALIBRATION DATA TEST", "THIS IS NOT A REAL VEHICLE SOFTWARE"]
    for t in texts:
        img.strings[t] = base + pos
        enc = t.encode("ascii") + b"\0"
        img.data[pos:pos + len(enc)] = enc
        pos += len(enc)
    pos = (pos + 3) & ~3
    ptr_targets = list(img.strings.values()) + [t.address for t in img.tables if t.kind == "map"]
    for p in ptr_targets:
        img.data[pos:pos + psize] = (p & ((1 << (8 * psize)) - 1)).to_bytes(psize, endian)
        pos += psize

    # ---- code
    code_start = {"arm-thumb": 0x200, "tricore": 0x100, "ppc": 0x100, "ppc-vle": 0x100, "8051": 0x100,
                  "c166": 0x200, "hc12": 0x100, "sh2": 0x400, "v850": 0x100, "m68k": 0x400}[arch]
    code_limit = calib - 0x100
    refs = [t.address for t in img.tables]
    enc = ENCODERS[arch]
    # two passes: first to learn entry addresses, then with calls to the real entries
    entries: list[int] = []
    for pass_ in range(2):
        a = _Asm(endian, base + code_start)
        xrefs: dict[int, list[int]] = {}
        r2 = random.Random(seed * 7919 + 1)
        cur: list[int] = []
        for i in range(n_funcs):
            if len(a.buf) + code_start > code_limit - 0x200:
                break
            if arch in ("arm-thumb", "ppc", "tricore", "m68k", "sh2", "v850", "ppc-vle", "c166"):
                a.align(4 if arch in ("arm-thumb", "ppc", "sh2") else 2, 0)
            cur.append(a.pc)
            # pass 1 calls a placeholder so every call has its final size and the entries don't move
            callees = entries if pass_ else [base + code_start]
            enc(a, r2, callees, refs, xrefs)
        entries = cur
    img.functions = entries
    img.xrefs = xrefs
    img.data[code_start:code_start + len(a.buf)] = a.buf
    img.code_end = code_start + len(a.buf)
    img.entry = entries[0] if entries else base

    # ---- vector table / boot header
    _vectors(img, arch, base, endian, entries)
    return img


def _vectors(img: SynthImage, arch: str, base: int, endian: str, entries: list[int]) -> None:
    d = img.data
    e = entries or [base]
    if arch == "arm-thumb":
        words = [0x20010000, e[0] | 1] + [(e[min(i, len(e) - 1)] | 1) if i % 3 else (e[-1] | 1) for i in range(2, 64)]
        d[0:len(words) * 4] = struct.pack("<%dI" % len(words), *words)
    elif arch in ("ppc", "ppc-vle"):
        d[0:8] = struct.pack(">II", 0x015A0000 if arch == "ppc-vle" else 0x005A0000, e[0])
    elif arch == "tricore":
        # AURIX boot mode header: BMI, BMHDID 0xB359, STAD
        d[0:8] = struct.pack("<HHI", 0x0370, 0xB359, e[0])
        d[0x20:0x24] = struct.pack("<I", 0x6D000000)            # padding word
    elif arch == "c166":
        for i in range(0, 0x80, 4):
            t = e[min(i // 4, len(e) - 1)]
            d[i:i + 4] = bytes([0xFA, (t >> 16) & 0xFF, t & 0xFF, (t >> 8) & 0xFF])   # jmps seg,addr
    elif arch == "hc12":
        end = len(d)
        for k in range(0, 0x80, 2):
            t = e[(k // 2) % len(e)] if k // 2 % 4 == 0 else e[-1]
            d[end - 0x80 + k:end - 0x80 + k + 2] = (t & 0xFFFF).to_bytes(2, "big")
        d[end - 2:end] = (e[0] & 0xFFFF).to_bytes(2, "big")
    elif arch == "sh2":
        words = [e[0], 0xFFFFFFF0, e[0], 0xFFFFFFF0] + [e[-1]] * 60
        d[0:len(words) * 4] = struct.pack(">%dI" % len(words), *words)
    elif arch == "v850":
        for i in range(0, 0x100, 0x10):
            t = e[min(i // 0x10, len(e) - 1)]
            disp = t - (base + i)
            d[i:i + 4] = struct.pack("<HH", (0 << 11) | (0x1E << 6) | ((disp >> 16) & 0x3F), disp & 0xFFFE)  # jr
    elif arch == "m68k":
        words = [0x00FFF000, e[0]] + [e[-1]] * 254
        d[0:len(words) * 4] = struct.pack(">%dI" % len(words), *words)
    elif arch == "8051":
        d[0:3] = bytes([0x02, e[0] >> 8, e[0] & 0xFF])          # ljmp main
        for v in (0x03, 0x0B, 0x13, 0x1B, 0x23):
            d[v] = 0x32                                          # reti
